from collections import deque
def comps(points):
 rem=set(points); out=[]
 while rem:
  p=rem.pop(); q=[p]; comp={p}
  while q:
   r,c=q.pop()
   for z in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
    if z in rem:rem.remove(z);comp.add(z);q.append(z)
  out.append(comp)
 return sorted(out,key=len,reverse=True)
[(len(x),(min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in comps(p1)],[(len(x),(min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in comps(outpts)]

